parameters.jsCode:
// 從 Gemini 回應中取出文字並解析成候選結構；格式錯誤或欄位缺漏時盡量降級輸出
// 空陣列／null，而不是整個請求失敗——後續是否 ready_for_draft 由 Django
// （inquiry_service.py 的 missing_fields 判斷）負責，這裡只做基本防呆與型別修正。
const text = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const cleaned = text.replace(/```json|```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parsed = {};
}

const toArray = value => (Array.isArray(value) ? value : []);
const toObject = value => (value && typeof value === 'object' && !Array.isArray(value) ? value : {});

const suppliers = toArray(parsed.suppliers)
  .map(row => ({ name: String((row && (row.name || row.supplier_name)) || '').trim() }))
  .filter(row => row.name);

const items = toArray(parsed.items).map(row => ({
  product_name: String((row && (row.product_name || row.name)) || '').trim(),
  quantity: row && row.quantity !== undefined && row.quantity !== null && row.quantity !== '' ? row.quantity : null,
  unit_of_measure: String((row && row.unit_of_measure) || 'EA'),
  specifications: toObject(row && row.specifications),
}));

return [{
  json: {
    purpose: String(parsed.purpose || '').trim(),
    needed_by: parsed.needed_by || null,
    currency: String(parsed.currency || 'TWD').toUpperCase(),
    assistant_message: String(parsed.assistant_message || '請確認 AI 整理的需求內容。'),
    suppliers,
    items,
  }
}];
